
// Blob encriptado (XOR)
const encryptedData = "";
const storedHash = "69829bede9842602948b0a5e7218cb55dce66989f305f34528d5e95e5bd5aa12";

function filterCards() {
  let input = document.getElementById("searchInput").value.toLowerCase();
  let sections = document.querySelectorAll("section");
  sections.forEach(section => {
    let cards = section.querySelectorAll(".card");
    let visibleCount = 0;
    cards.forEach(card => {
      let name = card.getAttribute("data-name");
      if (!input || name.includes(input)) {
        card.style.display = "block";
        visibleCount++;
      } else {
        card.style.display = "none";
      }
    });
    section.style.display = visibleCount > 0 ? "block" : "none";
  });
}


function clearSearch() {
  document.getElementById("searchInput").value = "";
  filterCards();
}


async function checkPassword() {
  const pass = document.getElementById("passwordInput").value;
  const overlay = document.getElementById("login-overlay");
  const app = document.getElementById("app-content");
  const error = document.getElementById("loginError");

  const msgBuffer = new TextEncoder().encode(pass);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');

  if (hashHex === storedHash) {
    try {
        error.textContent = "Desencriptando, por favor espere...";
        // Desencriptar y mostrar
        const decryptedHTML = decryptContent(encryptedData, hashHex);
        app.innerHTML = decryptedHTML;
        
        // Inicializar modales y eventos recién inyectados
        initModalEvents();
        
        overlay.style.opacity = "0";
        setTimeout(() => {
          overlay.style.display = "none";
          app.style.display = "block";
        }, 300);
    } catch (e) {
        console.error(e);
        error.textContent = "Error de desencriptación";
    }
  } else {
    error.textContent = "Contraseña incorrecta";
    document.getElementById("passwordInput").classList.add("shake");
    setTimeout(() => {
        document.getElementById("passwordInput").classList.remove("shake");
    }, 500);
  }
}

function hexToBytes(hex) {
    let bytes = [];
    for (let c = 0; c < hex.length; c += 2)
        bytes.push(parseInt(hex.substr(c, 2), 16));
    return new Uint8Array(bytes);
}

function decryptContent(encryptedHex, keyHex) {
    const encryptedBytes = hexToBytes(encryptedHex);
    const keyBytes = hexToBytes(keyHex);
    const resultBytes = new Uint8Array(encryptedBytes.length);
    
    // XOR Decryption
    for (let i = 0; i < encryptedBytes.length; i++) {
        resultBytes[i] = encryptedBytes[i] ^ keyBytes[i % keyBytes.length];
    }
    
    return new TextDecoder().decode(resultBytes);
}

document.getElementById("passwordInput").addEventListener("keypress", function(event) {
  if (event.key === "Enter") {
    checkPassword();
  }
});

let modal, modalImg, modalCaption, modalDelito, modalEdad, modalDNICE, modalSexo, modalLugar, modalFecha, modalSade, modalRecompensa, modalReincidente, galleryThumbs;
let galleryImages = [];
let currentGalleryIndex = 0;

function initModalEvents() {
    modal = document.getElementById('imageModal');
    modalImg = document.getElementById('modalImg');
    modalCaption = document.getElementById('modalCaption');
    modalDelito = document.getElementById('modalDelito');
    modalEdad = document.getElementById('modalEdad');
    modalDNICE = document.getElementById('modalDNICE');
    modalSexo = document.getElementById('modalSexo');
    modalLugar = document.getElementById('modalLugar');
    modalFecha = document.getElementById('modalFecha');
    modalSade = document.getElementById('modalSade');
    modalRecompensa = document.getElementById('modalRecompensa');
    modalReincidente = document.getElementById('modalReincidente');
    galleryThumbs = document.getElementById('galleryThumbs');

    modal.addEventListener('click', function(e) {
      if (e.target === this) closeModal();
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closeModal();
      if (e.key === 'ArrowLeft') prevGalleryImage();
      if (e.key === 'ArrowRight') nextGalleryImage();
    });
}

function openModal(principalId, name, delito, edad, dnice, sexo, lugar, fecha_formateada, sade, recompensa, reincidente, allImages) {
  modal.style.display = 'flex';
  
  galleryImages = allImages ? allImages.split('|') : [principalId];
  currentGalleryIndex = 0;
  
  updateGalleryImage();
  renderGalleryThumbs();
  
  modalCaption.textContent = name.replace(/\.[^/.]+$/, "").replaceAll("_", " ");
  modalDelito.textContent = delito ? "Delito: " + delito : "";
  modalEdad.textContent = edad || "-";
  modalDNICE.textContent = dnice || "-";
  modalSexo.textContent = sexo || "-";
  modalLugar.textContent = lugar || "-";
  modalFecha.textContent = fecha_formateada || "-";
  modalSade.textContent = sade || "-";
  modalRecompensa.textContent = recompensa || "S/ -";
  modalReincidente.textContent = reincidente || "-";   
}

function updateGalleryImage() {
  const imgId = galleryImages[currentGalleryIndex];
  modalImg.src = `https://drive.google.com/thumbnail?id=${imgId}&sz=w1000`;
  modalImg.alt = `Imagen ${currentGalleryIndex + 1}`;
  
  if (galleryThumbs) {
    const thumbs = galleryThumbs.querySelectorAll('.gallery-thumb');
    thumbs.forEach((thumb, idx) => {
      thumb.classList.toggle('active', idx === currentGalleryIndex);
    });
  }
}

function renderGalleryThumbs() {
  if (!galleryThumbs || galleryImages.length <= 1) {
    galleryThumbs.innerHTML = '';
    return;
  }
  
  galleryThumbs.innerHTML = galleryImages.map((imgId, idx) => {
    const thumbUrl = `https://drive.google.com/thumbnail?id=${imgId}&sz=w150`;
    return `<img src="${thumbUrl}" class="gallery-thumb ${idx === currentGalleryIndex ? 'active' : ''}" onclick="goToGalleryImage(${idx})" alt="Miniatura ${idx + 1}">`;
  }).join('');
  
  // Mostrar contador de imágenes
  galleryThumbs.innerHTML += `<span class="gallery-counter">${currentGalleryIndex + 1} / ${galleryImages.length}</span>`;
}

function goToGalleryImage(index) {
  currentGalleryIndex = index;
  updateGalleryImage();
}

function prevGalleryImage() {
  if (galleryImages.length > 1) {
    currentGalleryIndex = (currentGalleryIndex - 1 + galleryImages.length) % galleryImages.length;
    updateGalleryImage();
  }
}

function nextGalleryImage() {
  if (galleryImages.length > 1) {
    currentGalleryIndex = (currentGalleryIndex + 1) % galleryImages.length;
    updateGalleryImage();
  }
}

function closeModal() {
  modal.style.display = 'none';
  modalImg.src = '';
  galleryImages = [];
  currentGalleryIndex = 0;
  if (galleryThumbs) galleryThumbs.innerHTML = '';
  modalCaption.textContent = '';
  modalDelito.textContent = '';
  modalEdad.textContent = '';
  modalDNICE.textContent = '';
  modalSexo.textContent = '';
  modalLugar.textContent = '';
  modalFecha.textContent = '';
  modalSade.textContent = '';
  modalRecompensa.textContent = 'S/ -';
  modalReincidente.textContent = '';
}  
